.search-action,.search-input{
margin-bottom:-8px
}
.search form{
margin-bottom:8px
}
body.item-view .subscribe-section-container{
margin:5px 0 0 0;
width:100%
}
#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container .post-outer{
padding:0
}
.post:first-child{
margin:0
}
.post-body .snippet-thumbnail{
margin:0 3vw 3vw 0
}
.post-body .snippet-thumbnail img{
height:20vw;
width:20vw;
max-height:128px;
max-width:128px
}
div.widget.PopularPosts div.item-thumbnail{
margin:0 3vw 3vw 0
}
div.widget.PopularPosts div.item-thumbnail img{
height:20vw;
width:20vw;
max-height:88px;
max-width:88px
}
.post-title{
line-height:1
}
.post-title,.post-title a{
font-size:20px
}
#page_body.section div.widget.FeaturedPost h3 a{
font-size:22px
}
.mobile-ad .inline-ad{
display:block
}
.page_body.has-vertical-ads .vertical-ad-container,.page_body.has-vertical-ads .vertical-ad-container ins{
display:none
}
.page_body.has-vertical-ads .centered .centered-bottom,.page_body.has-vertical-ads .centered .centered-top{
display:block;
width:auto
}
div.post-filter-message div{
padding:8px 16px
}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{
position:relative
}
body.item-view .blog-name{
margin-left:48px
}
.page_body{
margin-left:$(sidebar.width)
}
.search{
margin-left:0
}
.search.focused{
width:100%
}
.sticky{
padding-left:$(sidebar.width)
}
.hamburger-menu{
display:none
}
body.collapsed-header .page_body .centered-top-container{
padding-left:$(sidebar.width);
padding-right:0;
width:100%
}
body.collapsed-header .centered-top-container .search.focused{
width:100%
}
body.collapsed-header .centered-top-container .blog-name{
margin-left:0
}
body.collapsed-header.item-view .centered-top-container .search.focused{
width:calc(100% - 50px)
}
body.collapsed-header.item-view .centered-top-container .blog-name{
margin-left:40px
}
}
/* LIFE MEDI media renewal - based on Blogger Indie */
:root{--lm-brand:#5267d9;--lm-brand-dark:#27346f;--lm-text:#20283a;--lm-muted:#6d7485;--lm-line:#e6e9f2;--lm-soft:#f4f6fb;--lm-point:#8ee1d2;--lm-radius:12px;--lm-shell:1200px;--lm-gutter:20px}
html{overflow-y:scroll;scrollbar-gutter:stable}
body{background:#fff;color:var(--lm-text);font-family:Pretendard,"Noto Sans KR","Apple SD Gothic Neo","Malgun Gothic",Arial,sans-serif}
.bg-photo-container,.bg-photo-overlay{display:none}
.page,.page_body{background:#fff}
.page_body .centered{display:flex!important;flex-direction:column!important;width:100%!important;max-width:none!important;min-height:100vh!important;margin:0!important;padding:0!important;box-sizing:border-box!important}
.centered-top-placeholder,.collapsed-header .centered-top-placeholder{display:none!important;width:0!important;height:0!important;min-height:0!important;padding:0!important;margin:0!important}
.centered-top-container{position:relative;width:100%!important;margin:0!important;padding:0!important;background:#fff;border-bottom:1px solid var(--lm-line);box-shadow:none!important;box-sizing:border-box!important}
.centered-top{width:100%;max-width:var(--lm-shell);margin:0 auto!important;padding:12px var(--lm-gutter) 0!important;box-sizing:border-box}
.blog-name,.item-view .blog-name{display:block!important;width:100%!important;min-height:0!important;margin:0!important;padding:0 0 12px!important;box-sizing:border-box!important;text-align:center!important}
.Header h1,.Header h2,.Header .title{display:block!important;width:100%!important;margin:0 0 8px!important;color:var(--lm-text)!important;font-size:30px!important;line-height:1.3!important;font-weight:800!important;letter-spacing:-.045em!important;text-align:center!important}
.Header h1 a,.Header h1 a:hover,.Header h1 a:visited,.Header h2 a,.Header h2 a:hover,.Header h2 a:visited,.Header .title a{color:var(--lm-text)!important;text-decoration:none!important}
.Header .description,.header-widget p{margin-top:5px;color:var(--lm-muted);font-size:14px}
.centered-top>.search,.centered-top>.return_link,.centered-top>.clearboth,.centered-top>.blog-name{display:none!important}
.centered-top{padding-top:0!important}
.lm-topbar{display:grid;grid-template-columns:minmax(210px,.8fr) minmax(320px,1.3fr) minmax(210px,.8fr);gap:32px;align-items:center;min-height:108px}
.lm-topbar-brand{display:inline-flex;align-items:center;width:230px;max-width:100%;text-decoration:none}
.lm-brand-logo{display:block;width:100%;height:auto;max-height:68px;object-fit:contain;object-position:left center}
.lm-brand-mark{display:inline-grid;place-items:center;width:38px;height:38px;color:var(--lm-brand);border:3px solid var(--lm-brand);border-radius:9px;font-size:24px;line-height:1;transform:rotate(45deg)}
.lm-brand-mark::first-letter{transform:rotate(-45deg)}
.lm-topbar-search{display:flex;align-items:center;gap:12px;height:54px;padding:0 18px;border:1px solid #e1e6f0;border-radius:9px;background:#e9edf5;box-sizing:border-box}
.lm-search-mark{color:#7b879d;font-size:28px;font-weight:800;line-height:1}
.lm-topbar-search input{width:100%;min-width:0;padding:0;border:0;outline:0;background:transparent;color:var(--lm-text);font:inherit;font-size:16px}
.lm-topbar-search input::placeholder{color:#77839a;opacity:1}
.lm-ad-rotator{justify-self:end;width:100%;max-width:300px;height:60px;overflow:hidden;border:1px solid var(--lm-line);border-radius:10px;background:#fff;box-shadow:0 8px 22px rgba(41,53,92,.07)}
.lm-ad-track{display:flex;flex-direction:column;animation:lmAdRoll 16s cubic-bezier(.65,0,.35,1) infinite}
.lm-ad-rotator:hover .lm-ad-track,.lm-ad-rotator:focus-within .lm-ad-track{animation-play-state:paused}
.lm-ad-banner{display:grid;grid-template-columns:auto minmax(0,1fr) auto;gap:10px;align-items:center;flex:0 0 60px;height:60px;padding:0 13px;color:var(--lm-text);text-decoration:none;box-sizing:border-box}
.lm-ad-badge{display:inline-flex;align-items:center;justify-content:center;min-width:30px;height:24px;padding:0 7px;color:#fff;font-size:10px;font-weight:900;letter-spacing:.05em;background:var(--lm-brand);border-radius:999px;box-sizing:border-box}
.lm-ad-copy{min-width:0}
.lm-ad-copy strong,.lm-ad-copy small{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.lm-ad-copy strong{font-size:13px;line-height:1.35}.lm-ad-copy small{margin-top:3px;color:var(--lm-muted);font-size:11px}
.lm-ad-arrow{color:var(--lm-brand);font-size:18px;font-weight:900}
@keyframes lmAdRoll{0%,21%{transform:translateY(0)}25%,46%{transform:translateY(-60px)}50%,71%{transform:translateY(-120px)}75%,96%{transform:translateY(-180px)}100%{transform:translateY(-240px)}}
@media(prefers-reduced-motion:reduce){.lm-ad-track{animation:none}.lm-ad-banner:not(:first-child){display:none}}
.lm-nav{padding:28px 0;background:#f5f6f8;border-top:1px solid var(--lm-line);border-bottom:1px solid var(--lm-line);overflow-x:auto;scrollbar-width:none}
.lm-nav::-webkit-scrollbar{display:none}
.lm-nav-inner{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:12px;width:100%;max-width:var(--lm-shell);margin:0 auto;padding:0 var(--lm-gutter);box-sizing:border-box;white-space:nowrap}
.lm-nav a{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:11px;min-height:108px;padding:14px 10px;color:#536078;font-size:15px;font-weight:800;text-align:center;text-decoration:none;background:#fff;border:1px solid #eceef4;border-radius:16px;box-shadow:0 8px 24px rgba(41,53,92,.07);transition:transform .2s ease,box-shadow .2s ease,color .2s ease}
.lm-nav a:hover{color:var(--lm-brand);transform:translateY(-2px);box-shadow:0 12px 30px rgba(41,53,92,.12)}
.lm-nav-icon{display:flex;align-items:center;justify-content:center;width:42px;height:42px;color:var(--lm-brand);font-family:"Segoe UI Emoji","Apple Color Emoji",sans-serif;font-size:27px;font-weight:400;line-height:1;background:#f0f3ff;border-radius:13px}
.vertical-ad-container{max-width:1200px;margin:16px auto}
.centered-bottom,.page_body.has-vertical-ads .centered .centered-bottom{display:block!important;width:100%!important;max-width:var(--lm-shell)!important;margin-right:auto!important;margin-left:auto!important;padding:32px var(--lm-gutter) 64px!important;box-sizing:border-box!important}
#main,#page_body,#Blog1,#Blog1 .widget-content{width:100%!important;min-width:0!important;box-sizing:border-box!important}
body.label-view #main,body.archive-view #main,body.search-view #main{float:none!important;clear:both!important}
body.label-view #page_body,body.archive-view #page_body,body.search-view #page_body,body.label-view #Blog1,body.archive-view #Blog1,body.search-view #Blog1{width:100%!important;max-width:none!important;margin-right:0!important;margin-left:0!important}
.main-heading{display:none}
.is-home #FeaturedPost1,.is-home .vertical-ad-container{display:none!important}
.is-home #main,.is-home #page_body,.is-home #Blog1,.is-home #Blog1 .widget-content{display:block!important;width:100%!important;max-width:1200px!important;min-width:0!important;margin-right:auto!important;margin-left:auto!important;box-sizing:border-box!important}
.is-home #Blog1 .blog-posts{display:grid!important;grid-template-columns:repeat(4,minmax(0,1fr))!important;gap:28px 18px!important;width:100%!important;margin:0!important;padding:0!important}
.is-home #Blog1 .blog-posts>.desktop-ad,.is-home #Blog1 .blog-posts>.mobile-ad{display:none!important}
.is-home #Blog1 .post-outer-container{display:block!important;width:auto!important;min-width:0!important;max-width:none!important;margin:0!important;padding:0!important;background:#fff!important;border:0!important;box-shadow:none!important}
.is-home #Blog1 .post-outer{display:block!important;width:auto!important;min-width:0!important;max-width:none!important;margin:0!important;padding:0!important;background:#fff!important;border:0!important;box-shadow:none!important}
.is-home #Blog1 .post{display:flex!important;flex-direction:column!important;width:100%!important;min-width:0!important;margin:0!important;padding:0!important;background:#fff!important;color:var(--lm-text)!important}
.is-home #Blog1 .post-title{order:1!important;float:none!important;width:100%!important;max-width:none!important;margin:10px 0 0!important;padding:0!important;color:var(--lm-text)!important;font-size:16px!important;line-height:1.45!important;letter-spacing:-.03em!important;writing-mode:horizontal-tb!important;word-break:keep-all!important;overflow-wrap:break-word!important}
.is-home #Blog1 .post-title a{display:-webkit-box!important;overflow:hidden!important;color:var(--lm-text)!important;text-decoration:none!important;-webkit-box-orient:vertical;-webkit-line-clamp:2}
.is-home #Blog1 .post-body.container{order:0!important;width:100%!important;max-width:none!important;margin:0!important;padding:0!important;background:#fff!important}
.is-home #Blog1 .post-body .snippet-thumbnail{float:none!important;width:100%!important;height:auto!important;margin:0!important;aspect-ratio:16/9;overflow:hidden;border-radius:var(--lm-radius);background:var(--lm-soft)}
.is-home #Blog1 .post-body .snippet-thumbnail img{display:block;width:100%!important;height:100%!important;object-fit:cover!important}
.is-home #Blog1 .post-body .snippet-item,.is-home #Blog1 .post-body .snippet-text,.is-home #Blog1 .post-share-buttons,.is-home #Blog1 .post-comment-link,.is-home #Blog1 .post-bottom,.is-home #Blog1 .jump-link{display:none!important}
.is-home #Blog1 .post-header,.is-home #Blog1 .post-footer{order:2!important;margin:8px 0 0!important;padding:0!important;background:#fff!important;color:var(--lm-muted)!important}
.is-home #Blog1 .byline,.is-home #Blog1 .byline a{color:var(--lm-muted)!important;font-size:12px!important}
.is-home #Blog1 .blog-pager{grid-column:1/-1;width:100%;margin-top:12px;text-align:center}
body:not(.item-view):not(.is-home) #Blog1 .post-outer-container{width:100%!important;margin:0 0 24px!important;padding:28px!important;background:#fff!important;border:1px solid var(--lm-line)!important;border-radius:14px!important;box-shadow:0 8px 26px rgba(20,55,53,.06)!important;box-sizing:border-box!important}
body:not(.item-view):not(.is-home) #Blog1 .post-outer,body:not(.item-view):not(.is-home) #Blog1 .post{background:#fff!important;color:var(--lm-text)!important;border:0!important;box-shadow:none!important}
body:not(.item-view):not(.is-home) #Blog1 .post-title,body:not(.item-view):not(.is-home) #Blog1 .post-title a,body:not(.item-view):not(.is-home) #Blog1 .post-title a:hover,body:not(.item-view):not(.is-home) #Blog1 .post-title a:visited{color:var(--lm-text)!important}
body:not(.item-view):not(.is-home) #Blog1 .post-title{float:none!important;width:100%!important;max-width:none!important;margin:0 0 12px!important;font-size:28px!important;line-height:1.4!important;word-break:keep-all!important}
body:not(.item-view):not(.is-home) #Blog1 .post-body,body:not(.item-view):not(.is-home) #Blog1 .post-body.container{background:#fff!important;color:#4d5655!important;line-height:1.75!important}
body:not(.item-view):not(.is-home) #Blog1 .post-header,body:not(.item-view):not(.is-home) #Blog1 .post-footer{background:#fff!important;color:var(--lm-muted)!important}
body:not(.item-view):not(.is-home) #Blog1 .byline,body:not(.item-view):not(.is-home) #Blog1 .byline a{color:var(--lm-muted)!important}
body:not(.item-view):not(.is-home) #Blog1 .post-share-buttons .svg-icon-24{fill:var(--lm-brand)!important}
body:not(.item-view):not(.is-home) #Blog1 .jump-link a{display:inline-flex!important;align-items:center!important;min-height:38px!important;padding:0 16px!important;background:var(--lm-brand)!important;color:#fff!important;border-radius:999px!important;text-decoration:none!important;font-weight:700!important}
body:not(.item-view):not(.is-home) #Blog1 .post-comment-link,body:not(.item-view):not(.is-home) #Blog1 .comment-link{display:none!important}
body:not(.item-view):not(.is-home) #Blog1 .post-snippet .snippet-fade{display:none!important;background:none!important;color:transparent!important}
body:not(.item-view):not(.is-home) #Blog1 .post-snippet{overflow:hidden!important}
body:not(.item-view):not(.is-home) .post-filter-message{margin:0 0 24px!important;padding:15px 18px!important;background:var(--lm-soft)!important;color:var(--lm-text)!important;border:1px solid var(--lm-line)!important;border-radius:10px!important}
body:not(.item-view):not(.is-home) .post-filter-message a{color:var(--lm-brand)!important;font-weight:700!important}
html,body,.page,.page_body,.centered,.centered-bottom,#main,#page_body{background:#fff!important}
.page_body{margin-left:0!important}
.sidebar-container,body.sidebar-visible .sidebar-container,.hamburger-menu{display:none!important}
.vertical-ad-container{display:none!important}
body.sidebar-visible{overflow:auto!important}
body.sidebar-visible .page_body{margin-left:0!important;transform:none!important}
.item-view .page_body,.item-view .centered,.item-view .centered-bottom,.item-view #main,.item-view #page_body,.item-view #Blog1,.item-view #Blog1 .widget-content,.item-view #Blog1 .blog-posts{background:#fff!important}
.item-view .page_body .centered{min-height:100vh!important}
.item-view .centered-top-container{margin:0!important}
.item-view .centered-top{padding-top:12px!important}
.item-view #header,.item-view .widget.Header{display:block!important;width:100%!important;margin:0!important}
.item-view .Header p{margin:0!important;color:var(--lm-muted)!important;text-align:center!important}
.item-view .lm-nav{margin:0!important}
.item-view .centered-bottom{display:block!important;width:100%!important;max-width:1200px!important;margin:0 auto!important;padding:32px 20px 72px!important;box-sizing:border-box!important}
.item-view #Blog1 .post-outer-container,.item-view #Blog1 .post-outer,.item-view #Blog1 .post{display:block!important;width:100%!important;max-width:1200px!important;min-width:0!important;margin:0!important;padding:0!important;border:0!important;box-shadow:none!important;background:#fff!important;color:var(--lm-text)!important;box-sizing:border-box!important}
.item-view #Blog1 .post-title{width:100%!important;margin:0 0 24px!important;padding:0!important;background:#fff!important;color:var(--lm-text)!important;font-size:clamp(30px,4vw,48px)!important;line-height:1.25!important;letter-spacing:-.045em!important;word-break:keep-all!important}
.item-view #Blog1 .post-body{width:100%!important;max-width:820px!important;margin:0!important;padding:0!important;background:#fff!important;color:#242424!important;font-size:18px!important;line-height:1.85!important;letter-spacing:-.01em!important;box-sizing:border-box!important}
.item-view #Blog1 .post-body img{max-width:100%!important;height:auto!important}
.item-view #Blog1 .post-footer,.item-view #comments,.item-view .comments{background:#fff!important;color:var(--lm-text)!important}
.item-view #comments,.item-view .comments,.item-view .comment-form,.item-view #comment-editor,.item-view .post-comment-link{display:none!important}
.item-view .post-body h2{margin:2.4em 0 .8em;padding:0 0 .55em;border-bottom:2px solid var(--lm-brand);font-size:28px;line-height:1.4;letter-spacing:-.035em}
.item-view .post-body h3{margin:2em 0 .65em;font-size:22px;line-height:1.45;letter-spacing:-.025em}
.item-view .post-body blockquote{margin:1.5em 0;padding:18px 20px;border-left:4px solid var(--lm-brand);background:var(--lm-soft);border-radius:0 10px 10px 0}
.item-view .post-body table{display:block;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch}
.item-view .post-body img{max-width:100%;height:auto;border-radius:10px}
/* FlexiBlog inspired article layout */
.item-view #Blog1 .post.lm-article-layout{display:grid!important;grid-template-columns:220px minmax(0,1fr)!important;column-gap:56px!important;align-items:start!important;width:100%!important;max-width:none!important}
.item-view #Blog1 .post.lm-article-layout>.post-title{grid-column:1/-1;max-width:1000px!important;margin:18px 0 22px!important;font-size:clamp(38px,5vw,64px)!important;line-height:1.14!important;font-weight:850!important}
.item-view #Blog1 .post.lm-article-layout>.post-header{grid-column:1/-1;display:flex!important;flex-wrap:wrap!important;gap:8px 18px!important;margin:0 0 32px!important;padding:0 0 22px!important;border-bottom:1px solid var(--lm-line)!important;color:var(--lm-muted)!important}
.item-view #Blog1 .post.lm-article-layout>.post-header a{color:var(--lm-brand)!important}
.lm-article-cover{grid-column:1/-1;width:100%;height:clamp(360px,48vw,620px);margin:0 0 52px;overflow:hidden;border-radius:16px 74px 16px 16px;background-color:var(--lm-soft);background-position:center;background-repeat:no-repeat;background-size:cover}
.lm-original-cover{display:none!important}
.lm-toc{grid-column:1;position:sticky;top:24px;padding:24px 20px;border:1px solid var(--lm-line);border-radius:14px;background:var(--lm-soft)}
.lm-toc-title{margin:0 0 16px;color:var(--lm-text);font-size:18px;font-weight:850}
.lm-toc-list{counter-reset:lm-toc;display:grid;gap:12px;margin:0;padding:0;list-style:none}
.lm-toc-list li{counter-increment:lm-toc;display:grid;grid-template-columns:28px minmax(0,1fr);gap:8px;align-items:start}
.lm-toc-list li:before{content:counter(lm-toc,decimal-leading-zero);color:#9ba4b7;font-size:12px;font-weight:800;line-height:1.7}
.lm-toc-list a{color:var(--lm-text);font-size:14px;font-weight:750;line-height:1.5;text-decoration:none}
.lm-toc-list a:hover{color:var(--lm-brand)}
.lm-article-side{display:grid;gap:26px;margin-top:26px;padding-top:24px;border-top:1px solid var(--lm-line)}
.lm-side-title{margin:0 0 14px;color:var(--lm-text);font-size:15px;font-weight:850;letter-spacing:-.02em}
.lm-side-posts{display:grid;gap:14px}
.lm-side-post{display:grid;grid-template-columns:64px minmax(0,1fr);gap:10px;align-items:center;color:var(--lm-text);text-decoration:none}
.lm-side-post-media{display:block;width:64px;height:56px;overflow:hidden;border-radius:8px;background:#e7ebf3}
.lm-side-post-media img{display:block;width:100%;height:100%;object-fit:cover}
.lm-side-post-title{display:-webkit-box;overflow:hidden;font-size:13px;font-weight:750;line-height:1.45;-webkit-box-orient:vertical;-webkit-line-clamp:3}
.lm-side-post:hover .lm-side-post-title{color:var(--lm-brand)}
.lm-side-links{display:flex;flex-wrap:wrap;gap:8px}
.lm-side-links a{display:inline-flex;align-items:center;min-height:30px;padding:0 10px;color:#556078;font-size:12px;font-weight:750;text-decoration:none;background:#fff;border:1px solid var(--lm-line);border-radius:999px}
.lm-side-links a:hover{color:#fff;background:var(--lm-brand);border-color:var(--lm-brand)}
.item-view #Blog1 .post.lm-article-layout>.post-body{grid-column:2;max-width:820px!important}
.item-view #Blog1 .post.lm-article-layout>.lm-related{grid-column:2;width:100%;max-width:820px;margin:64px 0 0}
.item-view #Blog1 .post.lm-article-layout>.post-bottom{grid-column:2;width:100%;max-width:820px;margin-top:32px;padding-top:24px;border-top:1px solid var(--lm-line)}
.item-view .post-body>h2:first-of-type{margin-top:0}
.item-view .post-body h2,.item-view .post-body h3{scroll-margin-top:28px}
.item-view .post-body ul,.item-view .post-body ol{padding-left:1.4em}
.item-view .post-body li{margin:.45em 0}
.item-view .post-body hr{margin:42px 0;border:0;border-top:1px solid var(--lm-line)}
.item-view .post-labels a{display:inline-flex;margin:4px 6px 4px 0;padding:7px 12px;border-radius:999px;background:var(--lm-soft);color:var(--lm-brand)!important;text-decoration:none}
.lm-home{background:#fff;padding:36px 0 0}
.lm-home-inner{width:100%;max-width:var(--lm-shell);margin:0 auto;padding:0 var(--lm-gutter);box-sizing:border-box}
.lm-section{margin:0 0 52px}
.lm-section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:18px;margin-bottom:18px}
.lm-section-title{margin:0;color:var(--lm-text);font-size:26px;line-height:1.35;letter-spacing:-.04em}
.lm-section-link{flex:0 0 auto;color:var(--lm-brand);font-size:14px;font-weight:700;text-decoration:none}
.lm-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:24px 18px}
.lm-hero-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}
.lm-card{min-width:0}
.lm-card-link{display:block;color:inherit;text-decoration:none}
.lm-card-media{position:relative;display:block;overflow:hidden;width:100%;aspect-ratio:16/9;background:linear-gradient(135deg,#dfecea,#f4f8f7);border-radius:var(--lm-radius)}
.lm-card-media:empty::before,.lm-card-media.is-placeholder::before,.lm-side-post-media:empty::before,.lm-side-post-media.is-placeholder::before{content:'LIFE MEDI';position:absolute;inset:0;display:flex;align-items:center;justify-content:center;color:var(--lm-brand);font-size:12px;font-weight:800;letter-spacing:.12em;background:linear-gradient(135deg,#e5f1ef,#f7faf9)}
.lm-card-media img{width:100%;height:100%;object-fit:cover;transition:transform .25s ease}
.lm-card-link:hover .lm-card-media img{transform:scale(1.025)}
.lm-card-body{display:block;padding:12px 2px 0}
.lm-card-label{display:block;margin-bottom:7px;color:var(--lm-brand);font-size:13px;font-weight:800}
.lm-card-title{display:-webkit-box;overflow:hidden;margin:0;color:var(--lm-text);font-size:18px;line-height:1.45;font-weight:750;letter-spacing:-.03em;-webkit-box-orient:vertical;-webkit-line-clamp:2}
.lm-card-excerpt{display:none;margin-top:10px;color:var(--lm-muted);font-size:14px;line-height:1.65}
.lm-card-date{display:block;margin-top:9px;color:#888;font-size:12px}
.lm-hero-card .lm-card-link{position:relative}
.lm-hero-card .lm-card-media:after{content:"";position:absolute;inset:40% 0 0;background:linear-gradient(transparent,rgba(0,0,0,.8))}
.lm-hero-card .lm-card-body{position:absolute;z-index:2;right:20px;bottom:20px;left:20px;padding:0}
.lm-hero-card .lm-card-label{color:var(--lm-point)}
.lm-hero-card .lm-card-title{color:#fff;font-size:24px;line-height:1.35;text-shadow:0 1px 3px rgba(0,0,0,.35)}
.lm-hero-card .lm-card-date{display:none}
/* FlexiBlog Science inspired home composition */
.is-home .centered-top-container{border-bottom:0}
.is-home .centered-top{padding-top:12px!important}
.is-home .lm-nav{border-top:1px solid var(--lm-line);border-bottom:1px solid var(--lm-line)}
.lm-kicker{display:block;margin-bottom:8px;color:var(--lm-brand);font-size:12px;font-weight:900;letter-spacing:.14em}
.lm-section{margin-bottom:72px}
.lm-section-title{font-size:30px;font-weight:850;letter-spacing:-.045em}
.lm-section-link{padding-bottom:4px;border-bottom:2px solid var(--lm-brand)}
.lm-flexi-hero .lm-section-head{margin-bottom:24px}
.lm-flexi-hero .lm-hero-grid{display:grid;grid-template-columns:minmax(0,1.55fr) minmax(280px,.85fr);grid-template-rows:repeat(2,238px);gap:20px}
.lm-flexi-hero .lm-hero-card:first-child{grid-row:1/3}
.lm-flexi-hero .lm-hero-card .lm-card-link,.lm-flexi-hero .lm-hero-card .lm-card-media{height:100%}
.lm-flexi-hero .lm-hero-card .lm-card-media{aspect-ratio:auto;border-radius:14px 64px 14px 14px}
.lm-flexi-hero .lm-hero-card:first-child .lm-card-title{font-size:36px;line-height:1.28}
.lm-flexi-hero .lm-hero-card:not(:first-child) .lm-card-title{font-size:20px}
.lm-flexi-hero .lm-hero-card .lm-card-media:after{inset:25% 0 0;background:linear-gradient(transparent,rgba(15,23,42,.9))}
.lm-flexi-trending .lm-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.lm-flexi-trending .lm-card{padding:12px;border:1px solid var(--lm-line);border-radius:14px;background:#fff;box-shadow:0 12px 32px rgba(41,53,92,.07)}
.lm-flexi-trending .lm-card-media{aspect-ratio:16/8.8}
.lm-flexi-editors{padding:42px;border-radius:24px;background:var(--lm-soft)}
.lm-flexi-editors .lm-grid{grid-template-columns:minmax(0,1.35fr) minmax(280px,.65fr);grid-template-rows:repeat(2,minmax(170px,1fr));gap:22px}
.lm-flexi-editors .lm-card:first-child{grid-row:1/3}
.lm-flexi-editors .lm-card:first-child .lm-card-media{aspect-ratio:16/10;border-radius:12px 54px 12px 12px}
.lm-flexi-editors .lm-card:first-child .lm-card-title{font-size:28px}
.lm-flexi-editors .lm-card:first-child .lm-card-excerpt{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2}
.lm-flexi-editors .lm-card:not(:first-child) .lm-card-link{display:grid;grid-template-columns:130px minmax(0,1fr);gap:16px;align-items:center;height:100%;padding:12px;background:#fff;border-radius:12px}
.lm-flexi-editors .lm-card:not(:first-child) .lm-card-media{height:100%;min-height:140px;aspect-ratio:auto}
.lm-flexi-editors .lm-card:not(:first-child) .lm-card-body{padding:0}
.lm-flexi-new .lm-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:24px}
.lm-flexi-new .lm-card-link{display:grid;grid-template-columns:minmax(150px,.85fr) minmax(0,1.15fr);gap:18px;align-items:center}
.lm-flexi-new .lm-card-media{aspect-ratio:4/3}
.lm-flexi-new .lm-card-body{padding:0}
.lm-flexi-new .lm-card-excerpt{display:-webkit-box;overflow:hidden;-webkit-box-orient:vertical;-webkit-line-clamp:2}
.lm-flexi-category{padding-top:8px;border-top:1px solid var(--lm-line)}
.lm-flexi-category .lm-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}
.lm-flexi-category .lm-card-media{border-radius:12px 38px 12px 12px}
.lm-latest-heading{padding-top:8px;border-top:1px solid var(--lm-line)}
.is-home #Blog1 .post-body .snippet-thumbnail{border-radius:12px 34px 12px 12px}
.is-home #Blog1 .blog-posts .post-title{margin-top:9px!important;font-size:15px!important;line-height:1.42!important;font-weight:750!important;letter-spacing:-.025em!important}
.is-home #Blog1 .blog-posts .post-title a{font-size:inherit!important;line-height:inherit!important;font-weight:inherit!important}
.lm-feed-status{grid-column:1/-1;padding:24px;color:var(--lm-muted);text-align:center;background:var(--lm-soft);border-radius:10px}
.lm-ad-slot,.lm-article-ad{display:none!important;margin:10px auto 48px;text-align:center}
.lm-latest-heading{width:100%;max-width:var(--lm-shell);margin:0 auto 18px}
.item-view #PopularPosts1,.is-home #PopularPosts1{display:none}
.lm-related{max-width:820px;margin:48px auto 0}
.lm-related .lm-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.lm-related .lm-card-title{font-size:15px}
#footer{display:none!important}
.lm-site-footer{width:100%;margin-top:72px;padding:64px var(--lm-gutter) 26px;background:#fff;border-top:1px solid var(--lm-line);box-sizing:border-box}
.lm-footer-inner{width:100%;max-width:var(--lm-shell);margin:0 auto}
.lm-footer-grid{display:grid;grid-template-columns:1.4fr repeat(3,minmax(150px,.75fr));gap:56px;padding-bottom:52px}
.lm-footer-brand{display:inline-flex;align-items:center;gap:12px;margin-bottom:18px;color:var(--lm-text);font-size:24px;font-weight:850;letter-spacing:-.04em}
.lm-footer-brand-mark{display:inline-grid;place-items:center;width:34px;height:34px;color:var(--lm-brand);border:3px solid var(--lm-brand);border-radius:8px;font-size:20px;transform:rotate(45deg)}
.lm-footer-intro p{max-width:320px;margin:0;color:var(--lm-muted);font-size:14px;line-height:1.75}
.lm-footer-column h3{margin:5px 0 18px;color:var(--lm-text);font-size:13px;font-weight:900;letter-spacing:.04em}
.lm-footer-column nav{display:grid;gap:11px}
.lm-footer-column a{color:#5f687b;font-size:14px;line-height:1.45;text-decoration:none}
.lm-footer-column a:hover{color:var(--lm-brand)}
.lm-footer-search{display:flex;align-items:center;height:44px;margin-top:22px;border:1px solid var(--lm-line);border-radius:8px;overflow:hidden;background:var(--lm-soft)}
.lm-footer-search input{width:100%;min-width:0;padding:0 13px;border:0;outline:0;background:transparent;color:var(--lm-text);font:inherit;font-size:13px}
.lm-footer-search button{align-self:stretch;width:46px;border:0;background:var(--lm-brand);color:#fff;font-size:20px;cursor:pointer}
.lm-footer-bottom{display:flex;align-items:center;justify-content:space-between;gap:24px;padding-top:24px;border-top:1px solid var(--lm-line);color:#747c8e;font-size:13px}
.lm-footer-legal{display:flex;flex-wrap:wrap;gap:14px 28px}
.lm-footer-legal a{color:#747c8e;text-decoration:none}
.lm-footer-legal a:hover{color:var(--lm-brand)}
@media(max-width:900px){
  .lm-footer-grid{grid-template-columns:1.25fr repeat(2,minmax(150px,.75fr));gap:38px}.lm-footer-intro{grid-column:1/-1}
  .lm-topbar{grid-template-columns:auto 1fr;gap:18px;min-height:0;padding:22px 0}.lm-topbar-search{grid-column:1/-1;grid-row:2}.lm-ad-rotator{max-width:280px}.lm-nav-inner{grid-template-columns:repeat(3,minmax(0,1fr))}
  .lm-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.lm-hero-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .lm-flexi-hero .lm-hero-grid{grid-template-columns:repeat(2,minmax(0,1fr));grid-template-rows:400px 220px}.lm-flexi-hero .lm-hero-card:first-child{grid-column:1/-1;grid-row:auto}
  .lm-flexi-editors{padding:30px}.lm-flexi-editors .lm-grid{grid-template-columns:1fr;grid-template-rows:auto}.lm-flexi-editors .lm-card:first-child{grid-row:auto}
  .item-view #Blog1 .post.lm-article-layout{grid-template-columns:1fr!important;width:100%!important;max-width:none!important}.item-view #Blog1 .post.lm-article-layout>*{grid-column:1!important}.lm-toc{position:relative;top:auto;margin:0 0 32px}.lm-article-cover{height:clamp(300px,56vw,480px);margin-bottom:36px;border-radius:14px 48px 14px 14px}
}
@media(min-width:768px){.is-home #Blog1 .blog-posts{grid-template-columns:repeat(4,minmax(0,1fr))!important}}
@media(max-width:767px){
  :root{--lm-gutter:18px}
  .centered-top{padding-top:8px}.blog-name{text-align:center}
  .centered-top{padding-top:0!important}.lm-topbar{grid-template-columns:minmax(120px,1fr) minmax(170px,220px);gap:12px;padding:18px 0}.lm-topbar-brand{width:180px;max-width:100%}.lm-ad-rotator{max-width:220px;height:54px}.lm-ad-banner{flex-basis:54px;height:54px;padding:0 10px}.lm-ad-track{animation-name:lmAdRollMobile}@keyframes lmAdRollMobile{0%,21%{transform:translateY(0)}25%,46%{transform:translateY(-54px)}50%,71%{transform:translateY(-108px)}75%,96%{transform:translateY(-162px)}100%{transform:translateY(-216px)}}.lm-topbar-search{height:48px}.lm-nav{padding:18px 0}.lm-nav-inner{display:flex;gap:12px;padding:0 var(--lm-gutter);overflow:visible}.lm-nav a{flex:0 0 145px;min-height:88px;padding:12px 10px;font-size:14px;border-radius:13px}.lm-nav-icon{font-size:24px}
  .lm-home{padding:28px 0 0}.lm-home-inner{padding-right:var(--lm-gutter);padding-left:var(--lm-gutter)}.lm-section{margin-bottom:42px}.lm-grid{gap:22px 12px}.lm-hero-grid{grid-template-columns:1fr;gap:14px}
  .lm-section-title{font-size:22px}.lm-card-title{font-size:15px}.lm-card-body{padding-top:9px}.lm-hero-card .lm-card-title{font-size:23px}
  .lm-flexi-hero .lm-hero-grid{grid-template-columns:1fr;grid-template-rows:340px 210px 210px}.lm-flexi-hero .lm-hero-card:first-child{grid-column:auto}.lm-flexi-hero .lm-hero-card:first-child .lm-card-title{font-size:27px}.lm-flexi-hero .lm-hero-card .lm-card-media{border-radius:12px 38px 12px 12px}
  .lm-flexi-trending .lm-grid,.lm-flexi-category .lm-grid,.lm-flexi-new .lm-grid{grid-template-columns:1fr}.lm-flexi-editors{padding:22px 18px;border-radius:16px}.lm-flexi-editors .lm-card:not(:first-child) .lm-card-link{grid-template-columns:110px minmax(0,1fr)}.lm-flexi-new .lm-card-link{grid-template-columns:120px minmax(0,1fr)}.lm-flexi-new .lm-card-excerpt{display:none}
  .centered-bottom,.page_body.has-vertical-ads .centered .centered-bottom{padding:28px 18px 48px!important}.is-home #Blog1 .blog-posts{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:22px 12px!important}.is-home #Blog1 .blog-posts .post-title{font-size:14px!important;line-height:1.4!important}
  body:not(.item-view):not(.is-home) #Blog1 .post-outer-container{padding:18px!important;border-radius:10px!important}body:not(.item-view):not(.is-home) #Blog1 .post-title{font-size:22px!important}
  .item-view .centered-bottom{padding-right:18px;padding-left:18px}.item-view .post-title{font-size:28px}.item-view .post-body{font-size:17px}.item-view .post-body h2{font-size:24px}.item-view .post-body h3{font-size:20px}.lm-related .lm-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:18px 10px}
  .item-view #Blog1 .post.lm-article-layout>.post-title{margin-top:8px!important;font-size:34px!important;line-height:1.22!important}.item-view #Blog1 .post.lm-article-layout>.post-header{margin-bottom:24px!important}.lm-article-cover{height:240px;margin-bottom:28px;border-radius:12px 34px 12px 12px}.lm-toc{padding:20px 18px}
  .lm-site-footer{margin-top:48px;padding:44px 18px 24px}.lm-footer-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:34px 22px;padding-bottom:36px}.lm-footer-intro{grid-column:1/-1}.lm-footer-bottom{align-items:flex-start;flex-direction:column}.lm-footer-legal{gap:10px 18px}
}
@media(max-width:479px){.lm-grid,.is-home .blog-posts{gap:20px 10px}.lm-card-title{font-size:14px}.lm-hero-card .lm-card-title{font-size:21px}}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

body.script:
//
(function(){
  'use strict';
  var feedCache={};
  function setText(node,value){node.textContent=value||'';return node}
  function alternate(entry){var links=entry.link||[];for(var i=0;i<links.length;i++){if(links[i].rel==='alternate'){return links[i].href}}return '#'}
  function imageUrl(entry){
    var url=entry.media$thumbnail&&entry.media$thumbnail.url?entry.media$thumbnail.url:'';
    if(!url&&entry.content&&entry.content.$t){var match=entry.content.$t.match(/<img[^>]+src=["']([^"']+)/i);url=match?match[1]:''}
    return url.replace(/\/s72-c\//,'/w640-h360-p-k-no-nu/').replace(/=s72-c$/,'=w640-h360-p-k-no-nu');
  }
  function dateText(entry){var raw=(entry.published&&entry.published.$t)||(entry.updated&&entry.updated.$t)||'';if(!raw){return ''}var d=new Date(raw);return isNaN(d.getTime())?'':d.toLocaleDateString('ko-KR',{year:'numeric',month:'2-digit',day:'2-digit'})}
  function excerpt(entry){var raw=(entry.summary&&entry.summary.$t)||(entry.content&&entry.content.$t)||'';var box=document.createElement('div');box.innerHTML=raw;return (box.textContent||box.innerText||'').replace(/\s+/g,' ').trim().slice(0,120)}
  function fromEntry(entry){return {title:entry.title?entry.title.$t:'제목 없음',url:alternate(entry),image:imageUrl(entry),label:entry.category&&entry.category[0]?entry.category[0].term:'건강정보',date:dateText(entry),excerpt:excerpt(entry)}}
  function card(data,hero){
    var article=document.createElement('article');article.className='lm-card'+(hero?' lm-hero-card':'');
    var link=document.createElement('a');link.className='lm-card-link';link.href=data.url||'#';
    var media=document.createElement('span');media.className='lm-card-media';
    if(data.image){var img=document.createElement('img');img.loading='lazy';img.decoding='async';img.src=data.image;img.alt=data.title||'건강정보 썸네일';img.addEventListener('error',function(){img.remove();media.classList.add('is-placeholder')},{once:true});media.appendChild(img)}
    var body=document.createElement('span');body.className='lm-card-body';
    body.appendChild(setText(document.createElement('span'),data.label||'건강정보')).className='lm-card-label';
    body.appendChild(setText(document.createElement('span'),data.title||'제목 없음')).className='lm-card-title';
    body.appendChild(setText(document.createElement('span'),data.excerpt||'')).className='lm-card-excerpt';
    body.appendChild(setText(document.createElement('time'),data.date||'')).className='lm-card-date';
    link.appendChild(media);link.appendChild(body);article.appendChild(link);return article;
  }
  function render(container,items,hero){
    var section=container.closest('.lm-section');
    container.textContent='';
    if(!items.length){if(section){section.hidden=true}else{container.hidden=true}return}
    if(section){section.hidden=false}else{container.hidden=false}
    items.forEach(function(item){container.appendChild(card(item,hero))})
  }
  function feed(label,limit){
    var path='/feeds/posts/default'+(label&&label!=='recent'?'/-/'+encodeURIComponent(label):'');
    var url=path+'?alt=json&max-results='+limit;
    if(feedCache[url]){return feedCache[url]}
    var request=fetch(url,{credentials:'same-origin'}).then(function(response){if(!response.ok){throw new Error('Feed HTTP '+response.status)}return response.json()}).then(function(json){return ((json.feed&&json.feed.entry)||[]).map(fromEntry)});
    var timeout=new Promise(function(resolve,reject){setTimeout(function(){reject(new Error('Feed timeout'))},8000)});
    feedCache[url]=Promise.race([request,timeout]).catch(function(error){delete feedCache[url];throw error});
    return feedCache[url];
  }
  function nativePopular(limit){
    var links=document.querySelectorAll('#PopularPosts1 .post-title a,#PopularPosts1 .item-title a,#PopularPosts1 h3 a');var items=[];
    for(var i=0;i<links.length&&items.length<limit;i++){var a=links[i],root=a.closest('li,article,.post,.item-content')||a.parentNode,img=root&&root.querySelector('img');items.push({title:a.textContent.trim(),url:a.href,image:img?img.src:'',label:'인기',date:''})}
    return items;
  }
  function initFeeds(){
    document.querySelectorAll('[data-lm-feed]').forEach(function(block){var type=block.getAttribute('data-lm-feed'),limit=parseInt(block.getAttribute('data-limit'),10)||4;
      if(type==='popular'){var popular=nativePopular(limit);if(popular.length){render(block,popular,false)}else{feed('recent',limit).then(function(items){render(block,items,false)}).catch(function(){render(block,[],false)})};return}
      if(type==='related'){var section=block.closest('.lm-related'),label=section?section.getAttribute('data-label'):'',current=section?section.getAttribute('data-current'):'';feed(label,limit+1).then(function(items){items=items.filter(function(item){return item.url!==current});if(items.length>=limit){render(block,items.slice(0,limit),false);return}feed('recent',limit+1).then(function(recent){var seen={};items.forEach(function(item){seen[item.url]=true});recent.forEach(function(item){if(item.url!==current&&!seen[item.url]&&items.length<limit){seen[item.url]=true;items.push(item)}});render(block,items.slice(0,limit),false)}).catch(function(){render(block,items.slice(0,limit),false)})}).catch(function(){feed('recent',limit+1).then(function(items){render(block,items.filter(function(item){return item.url!==current}).slice(0,limit),false)}).catch(function(){render(block,[],false)})});return}
      feed(block.getAttribute('data-label')||'recent',limit).then(function(items){render(block,items,type==='hero')}).catch(function(){render(block,[],type==='hero')});
    });
  }
  function sideLinks(title,links){
    var section=document.createElement('section'),heading=document.createElement('h3'),wrap=document.createElement('div');heading.className='lm-side-title';heading.textContent=title;wrap.className='lm-side-links';
    links.forEach(function(data){var link=document.createElement('a');link.href=data[1];link.textContent=data[0];wrap.appendChild(link)});section.appendChild(heading);section.appendChild(wrap);return section;
  }
  function renderSidePosts(container,items){
    container.textContent='';items.slice(0,3).forEach(function(data){var link=document.createElement('a'),media=document.createElement('span'),title=document.createElement('span');link.className='lm-side-post';link.href=data.url||'#';media.className='lm-side-post-media';if(data.image){var img=document.createElement('img');img.loading='lazy';img.decoding='async';img.src=data.image;img.alt='';img.addEventListener('error',function(){img.remove();media.classList.add('is-placeholder')},{once:true});media.appendChild(img)}title.className='lm-side-post-title';title.textContent=data.title||'건강정보';link.appendChild(media);link.appendChild(title);container.appendChild(link)});
  }
  function appendArticleSide(toc){
    var side=document.createElement('div');side.className='lm-article-side';
    var popular=document.createElement('section'),heading=document.createElement('h3'),posts=document.createElement('div');heading.className='lm-side-title';heading.textContent='많이 읽은 건강정보';posts.className='lm-side-posts';popular.appendChild(heading);popular.appendChild(posts);side.appendChild(popular);
    side.appendChild(sideLinks('주요 카테고리',[["질환·증상","/search/label/질환·증상"],["혈당·당뇨","/search/label/혈당·당뇨"],["영양·식습관","/search/label/영양·식습관"],["눈 건강","/search/label/눈 건강"],["생활건강","/search/label/생활건강"],["의학·건강뉴스","/search/label/의학·건강뉴스"]]));
    side.appendChild(sideLinks('주요 태그',[["블루라이트 차단 안경","/search/label/블루라이트 차단 안경"],["임상 연구","/search/label/임상 연구"],["통풍","/search/label/통풍"],["지방간","/search/label/지방간"]]));toc.appendChild(side);
    var items=nativePopular(3);if(items.length){renderSidePosts(posts,items)}else{feed('recent',3).then(function(recent){renderSidePosts(posts,recent)}).catch(function(){popular.hidden=true})}
  }
  function initArticleLayout(){
    var post=document.querySelector('.item-view #Blog1 .post'),body=post&&post.querySelector('.post-body.entry-content');
    if(!post||!body){return}
    post.classList.add('lm-article-layout');
    body.querySelectorAll('h1').forEach(function(heading){var replacement=document.createElement('h2');for(var i=0;i<heading.attributes.length;i++){replacement.setAttribute(heading.attributes[i].name,heading.attributes[i].value)}replacement.innerHTML=heading.innerHTML;heading.parentNode.replaceChild(replacement,heading)});
    var firstImage=body.querySelector('img');
    if(firstImage){
      var source=firstImage.closest('.separator')||firstImage.closest('a')||firstImage;
      source.classList.add('lm-original-cover');
    }
    var headings=body.querySelectorAll('h2,h3');
    if(headings.length){
      var toc=document.createElement('nav');toc.className='lm-toc';toc.setAttribute('aria-label','목차');
      var title=document.createElement('h2');title.className='lm-toc-title';title.textContent='목차';toc.appendChild(title);
      var list=document.createElement('ol');list.className='lm-toc-list';
      headings.forEach(function(heading,index){if(!heading.id){heading.id='lm-article-section-'+(index+1)}var item=document.createElement('li'),link=document.createElement('a');link.href='#'+heading.id;link.textContent=heading.textContent.trim();item.appendChild(link);list.appendChild(item)});
      toc.appendChild(list);appendArticleSide(toc);post.insertBefore(toc,body);
    }
  }
  function placeMiddleAd(){var slot=document.getElementById('ad-article-middle'),body=document.querySelector('.item-view .post-body.entry-content');if(!slot||!body){return}var headings=body.querySelectorAll('h2');if(headings.length>1){headings[1].parentNode.insertBefore(slot,headings[1])}}
  function initListView(){
    if(document.body.classList.contains('item-view')||document.body.classList.contains('is-home')){return}
    var message=document.querySelector('.post-filter-message > div:first-child');
    var labelMatch=window.location.pathname.match(/\/search\/label\/([^/?#]+)/i);
    if(message&&labelMatch){
      var label='';
      try{label=decodeURIComponent(labelMatch[1]).replace(/\+/g,' ')}catch(error){label=labelMatch[1]}
      var count=document.querySelectorAll('#Blog1 .post-outer-container').length;
      message.textContent=label+' 게시글 '+count+'개';
    }
  }
  if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',function(){initArticleLayout();initFeeds();placeMiddleAd();initListView()})}else{initArticleLayout();initFeeds();placeMiddleAd();initListView()}
})();
